        mockMvc.perform(post(FOLLOW_UP_URL, KNOWN_CASE)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(body))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.message", containsString("extracted_at")));
    }

    // -------------------------------------------------------------------------
    // Happy path — merged response shape
    // -------------------------------------------------------------------------

